mapper.select:
SELECT ,
       s.name AS student_name, s.student_no AS student_no,
       u.real_name AS counselor_name
FROM leave_request l
LEFT JOIN student s ON l.student_id = s.id
LEFT JOIN sys_user u ON l.counselor_id = u.id

    AND s.name LIKE CONCAT('%', #{studentName}, '%')
    AND l.leave_type = #{leaveType}
    AND l.status = #{status}
    AND l.student_id = #{studentId}
    AND l.counselor_id = #{counselorId}

ORDER BY l.create_time DESC, l.id DESC

mapper.update:
UPDATE leave_request
student_id = #{studentId}, leave_type = #{leaveType}, start_date = #{startDate}, end_date = #{endDate}, days = #{days}, reason = #{reason}, status = #{status}, counselor_id = #{counselorId}, approve_time = #{approveTime},
WHERE id = #{id}
